const prompts=['What did you notice before deciding what it means?','Whose perspective is missing from this story?','What repair is yours to offer—and yours to decline?','Where is the visible exit from this commitment?','What note would help you return after an interruption?'];let index=0;document.getElementById('next-prompt').addEventListener('click',()=>{index=(index+1)%prompts.length;document.getElementById('practice-prompt').textContent=prompts[index]});